-- =====================================================================
-- PSP disputes/refunds, notifications, regulatory reporting, channels
-- GENERATED by tools/codegen/gen_ddl.py from disputes.spec, notify.spec, reporting.spec, channels.spec
-- (same specs as the JPA entities). Edit the spec, regenerate, never hand-edit.
-- =====================================================================

-- Ledger side of a dispute: what was held from the merchant, the response deadline and the financial outcome.
CREATE TABLE psp_dispute_cases (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    dispute_id                   BIGINT NOT NULL,
    merchant_id                  BIGINT NOT NULL,
    checkout_session_id          BIGINT NOT NULL,
    transaction_reference        VARCHAR(60),
    currency                     VARCHAR(3) NOT NULL,
    disputed_minor               BIGINT NOT NULL DEFAULT 0,
    held_minor                   BIGINT NOT NULL DEFAULT 0,
    shortfall_minor              BIGINT NOT NULL DEFAULT 0,
    status                       VARCHAR(20) NOT NULL,
    respond_by                   DATETIME(6) NOT NULL,
    hold_entry_ref               VARCHAR(40),
    outcome_entry_ref            VARCHAR(40),
    outcome                      VARCHAR(20),
    decided_by                   VARCHAR(120),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_dispute_cases_dispute_id UNIQUE (dispute_id),
    INDEX idx_dcase_status (status,respond_by)
);

-- Money owed back to a customer (merchant refund, chargeback, consumer refund) until it is actually paid out.
CREATE TABLE psp_customer_refunds (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    refund_ref                   VARCHAR(40) NOT NULL,
    source_type                  VARCHAR(30) NOT NULL,
    source_ref                   VARCHAR(120) NOT NULL,
    merchant_id                  BIGINT,
    currency                     VARCHAR(3) NOT NULL,
    amount_minor                 BIGINT NOT NULL DEFAULT 0,
    customer_msisdn              VARCHAR(20),
    status                       VARCHAR(20) NOT NULL,
    funding_entry_ref            VARCHAR(40),
    payout_entry_ref             VARCHAR(40),
    payout_method                VARCHAR(30),
    payout_reference             VARCHAR(150),
    paid_by                      VARCHAR(120),
    paid_at                      DATETIME(6),
    failure_reason               VARCHAR(500),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_customer_refunds_refund_ref UNIQUE (refund_ref),
    INDEX idx_crefund_status (status,created_at),
    CONSTRAINT uq_crefund_source UNIQUE (source_type,source_ref)
);

-- Message templates per event, channel and language. Placeholders: {{name}}. Edited by ops without a release.
CREATE TABLE psp_notification_templates (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    code                         VARCHAR(60) NOT NULL,
    channel                      VARCHAR(20) NOT NULL,
    locale                       VARCHAR(5) NOT NULL,
    subject                      VARCHAR(200),
    body                         TEXT NOT NULL,
    active                       BOOLEAN NOT NULL DEFAULT FALSE,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_ntpl UNIQUE (code,channel,locale)
);

-- One outbound message with delivery status and retries.
CREATE TABLE psp_notifications (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    notification_ref             VARCHAR(40) NOT NULL,
    dedupe_key                   VARCHAR(160) NOT NULL,
    channel                      VARCHAR(20) NOT NULL,
    recipient                    VARCHAR(200) NOT NULL,
    template_code                VARCHAR(60) NOT NULL,
    subject                      VARCHAR(200),
    body                         TEXT NOT NULL,
    status                       VARCHAR(20) NOT NULL,
    attempts                     INT NOT NULL DEFAULT 0,
    next_attempt_at              DATETIME(6) NOT NULL,
    provider_ref                 VARCHAR(200),
    last_error                   VARCHAR(1000),
    sent_at                      DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_notifications_notification_ref UNIQUE (notification_ref),
    INDEX idx_notif_status (status,next_attempt_at),
    CONSTRAINT uq_notif_dedupe UNIQUE (dedupe_key)
);

-- A generated regulatory / tax return with its data, hash and submission trail. Reviewed by a second person before submission.
CREATE TABLE psp_regulatory_reports (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    report_ref                   VARCHAR(40) NOT NULL,
    report_type                  VARCHAR(40) NOT NULL,
    period_start                 DATETIME(6) NOT NULL,
    period_end                   DATETIME(6) NOT NULL,
    status                       VARCHAR(20) NOT NULL,
    payload_json                 TEXT NOT NULL,
    csv                          TEXT,
    sha256                       VARCHAR(64) NOT NULL,
    generated_by                 VARCHAR(120) NOT NULL,
    reviewed_by                  VARCHAR(120),
    reviewed_at                  DATETIME(6),
    submitted_by                 VARCHAR(120),
    submitted_at                 DATETIME(6),
    submission_ref               VARCHAR(150),
    created_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_regulatory_reports_report_ref UNIQUE (report_ref),
    INDEX idx_rr_type_period (report_type,period_start)
);

-- An API partner (aggregator, bank, fintech, large merchant) authenticated by HMAC request signing and optionally mTLS.
CREATE TABLE psp_partner_clients (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    key_id                       VARCHAR(40) NOT NULL,
    name                         VARCHAR(200) NOT NULL,
    merchant_id                  BIGINT,
    secret                       VARCHAR(600) NOT NULL,
    scopes                       VARCHAR(500) NOT NULL,
    allowed_ips                  VARCHAR(1000),
    mtls_cert_sha256             VARCHAR(64),
    status                       VARCHAR(20) NOT NULL,
    rate_limit_per_minute        INT NOT NULL DEFAULT 0,
    created_by                   VARCHAR(120) NOT NULL,
    last_used_at                 DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_partner_clients_key_id UNIQUE (key_id),
    INDEX idx_partner_merchant (merchant_id)
);

-- Replay protection for signed requests: a (client, nonce) pair is accepted once. Purged after 15 minutes.
CREATE TABLE psp_request_nonces (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    client_id                    VARCHAR(40) NOT NULL,
    nonce                        VARCHAR(80) NOT NULL,
    created_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_nonce UNIQUE (client_id,nonce),
    INDEX idx_nonce_created (created_at)
);

-- A POS / mPOS / SoftPOS terminal assigned to a merchant. Authenticates with its own HMAC secret.
CREATE TABLE psp_terminals (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    terminal_id                  VARCHAR(16) NOT NULL,
    merchant_id                  BIGINT NOT NULL,
    terminal_type                VARCHAR(10) NOT NULL,
    serial_number                VARCHAR(80),
    model                        VARCHAR(80),
    location_label               VARCHAR(200),
    secret                       VARCHAR(600) NOT NULL,
    status                       VARCHAR(20) NOT NULL,
    last_seen_at                 DATETIME(6),
    app_version                  VARCHAR(40),
    assigned_by                  VARCHAR(120) NOT NULL,
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_terminals_terminal_id UNIQUE (terminal_id),
    INDEX idx_terminal_merchant (merchant_id)
);

-- Conversation state for the WhatsApp bot, keyed by WhatsApp number.
CREATE TABLE psp_chat_sessions (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    channel                      VARCHAR(20) NOT NULL,
    user_ref                     VARCHAR(40) NOT NULL,
    state                        VARCHAR(40) NOT NULL,
    data                         TEXT,
    expires_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_chat_channel_user UNIQUE (channel,user_ref)
);
